import{_ as e,o as d,c as l,ao as a}from"./chunks/framework.AQkxRU0n.js";const x=JSON.parse('{"title":"Julia API の実測対応表","description":"","frontmatter":{},"headers":[],"relativePath":"reference/support-matrix.md","filePath":"reference/support-matrix.md","lastUpdated":null}'),i={name:"reference/support-matrix.md"};function r(o,t,c,s,g,n){return d(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="Julia-API-の実測対応表" tabindex="-1">Julia API の実測対応表 <a class="header-anchor" href="#Julia-API-の実測対応表" aria-label="Permalink to &quot;Julia API の実測対応表 {#Julia-API-の実測対応表}&quot;">​</a></h1><p>通常配列の呼び出しが成功するかと、その入口を Colmat が提供するかを分けて記録します。 入口は Julia 1.13 のラッパー実装から選び、LBT の登録先を照合します。動的な呼び出し回数の計測やライブラリ内部を追跡したトレースではありません。</p><h2 id="検証条件" tabindex="-1">検証条件 <a class="header-anchor" href="#検証条件" aria-label="Permalink to &quot;検証条件 {#検証条件}&quot;">​</a></h2><ul><li><p>Julia: <code>1.13.3</code> / <code>x86_64-linux-gnu</code>。</p></li><li><p>Colmat ソース: <code>bc0dce2af48590dec20f99976ad7aee8b999a447</code>。</p></li><li><p>Rust colmat ソース: <code>e1c83482f5a61449d30e989808c3ba5f751ec391</code>。</p></li><li><p>Julia の BLAS 整数 ABI: <code>ilp64</code>。</p></li><li><p>Colmat 実行幅: <code>1</code>。</p></li><li><p>要素型は Float32 / Float64 / ComplexF32 / ComplexF64 の順。</p></li></ul><h2 id="実行結果" tabindex="-1">実行結果 <a class="header-anchor" href="#実行結果" aria-label="Permalink to &quot;実行結果 {#実行結果}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Julia API</th><th style="text-align:right;">Float32</th><th style="text-align:right;">Float64</th><th style="text-align:right;">ComplexF32</th><th style="text-align:right;">ComplexF64</th><th style="text-align:right;">主な入口の登録先</th><th style="text-align:right;">Rust 側の実装・接続</th></tr></thead><tbody><tr><td style="text-align:right;"><code>A * B</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">行列積</td></tr><tr><td style="text-align:right;"><code>mul!(C, A, B)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">行列積</td></tr><tr><td style="text-align:right;"><code>A * x</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">行列積</td></tr><tr><td style="text-align:right;"><code>dot(x, x)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>norm(x)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>BLAS.axpy!</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>UpperTriangular(A) \\ x</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>UpperTriangular(A) \\ B</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>lu(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">partial_piv_lu（接続済み）</td></tr><tr><td style="text-align:right;"><code>lu(A) \\ x</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">LU solve（接続済み）</td></tr><tr><td style="text-align:right;"><code>qr(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">既存バックエンド</td><td style="text-align:right;">qr（未接続）</td></tr><tr><td style="text-align:right;"><code>qr(A, ColumnNorm())</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">既存バックエンド</td><td style="text-align:right;">col_piv_qr（未接続）</td></tr><tr><td style="text-align:right;"><code>svd(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">svd（接続済み）</td></tr><tr><td style="text-align:right;"><code>svd(A; alg=LinearAlgebra.QRIteration())</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">svd（接続済み）</td></tr><tr><td style="text-align:right;"><code>svdvals(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">SVD（接続済み）</td></tr><tr><td style="text-align:right;"><code>eigen(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">eigen（接続済み）</td></tr><tr><td style="text-align:right;"><code>eigen(Hermitian(A))</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">self_adjoint_eigen（接続済み）</td></tr><tr><td style="text-align:right;"><code>cholesky(Hermitian(A))</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">llt（接続済み）</td></tr></tbody></table><h2 id="入口シンボルと実際のライブラリ" tabindex="-1">入口シンボルと実際のライブラリ <a class="header-anchor" href="#入口シンボルと実際のライブラリ" aria-label="Permalink to &quot;入口シンボルと実際のライブラリ {#入口シンボルと実際のライブラリ}&quot;">​</a></h2><p>各行は上表と同じ API を確認しています。シンボルは上記4型の順です。</p><table tabindex="0"><thead><tr><th style="text-align:right;">Julia API</th><th style="text-align:right;">確認した入口</th><th style="text-align:right;">LBT の登録先</th></tr></thead><tbody><tr><td style="text-align:right;"><code>A * B</code></td><td style="text-align:right;"><code>sgemm_</code>, <code>dgemm_</code>, <code>cgemm_</code>, <code>zgemm_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>mul!(C, A, B)</code></td><td style="text-align:right;"><code>sgemm_</code>, <code>dgemm_</code>, <code>cgemm_</code>, <code>zgemm_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>A * x</code></td><td style="text-align:right;"><code>sgemv_</code>, <code>dgemv_</code>, <code>cgemv_</code>, <code>zgemv_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>dot(x, x)</code></td><td style="text-align:right;"><code>cblas_sdot</code>, <code>cblas_ddot</code>, <code>cblas_cdotc_sub</code>, <code>cblas_zdotc_sub</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>norm(x)</code></td><td style="text-align:right;"><code>snrm2_</code>, <code>dnrm2_</code>, <code>scnrm2_</code>, <code>dznrm2_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>BLAS.axpy!</code></td><td style="text-align:right;"><code>saxpy_</code>, <code>daxpy_</code>, <code>caxpy_</code>, <code>zaxpy_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>UpperTriangular(A) \\ x</code></td><td style="text-align:right;"><code>strsv_</code>, <code>dtrsv_</code>, <code>ctrsv_</code>, <code>ztrsv_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>UpperTriangular(A) \\ B</code></td><td style="text-align:right;"><code>strsm_</code>, <code>dtrsm_</code>, <code>ctrsm_</code>, <code>ztrsm_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>lu(A)</code></td><td style="text-align:right;"><code>sgetrf_</code>, <code>dgetrf_</code>, <code>cgetrf_</code>, <code>zgetrf_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>lu(A) \\ x</code></td><td style="text-align:right;"><code>sgetrs_</code>, <code>dgetrs_</code>, <code>cgetrs_</code>, <code>zgetrs_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>qr(A)</code></td><td style="text-align:right;"><code>sgeqrt_</code>, <code>dgeqrt_</code>, <code>cgeqrt_</code>, <code>zgeqrt_</code></td><td style="text-align:right;"><code>libopenblas64_.so</code></td></tr><tr><td style="text-align:right;"><code>qr(A, ColumnNorm())</code></td><td style="text-align:right;"><code>sgeqp3_</code>, <code>dgeqp3_</code>, <code>cgeqp3_</code>, <code>zgeqp3_</code></td><td style="text-align:right;"><code>libopenblas64_.so</code></td></tr><tr><td style="text-align:right;"><code>svd(A)</code></td><td style="text-align:right;"><code>sgesdd_</code>, <code>dgesdd_</code>, <code>cgesdd_</code>, <code>zgesdd_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>svd(A; alg=LinearAlgebra.QRIteration())</code></td><td style="text-align:right;"><code>sgesvd_</code>, <code>dgesvd_</code>, <code>cgesvd_</code>, <code>zgesvd_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>svdvals(A)</code></td><td style="text-align:right;"><code>sgesdd_</code>, <code>dgesdd_</code>, <code>cgesdd_</code>, <code>zgesdd_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>eigen(A)</code></td><td style="text-align:right;"><code>sgeevx_</code>, <code>dgeevx_</code>, <code>cgeevx_</code>, <code>zgeevx_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>eigen(Hermitian(A))</code></td><td style="text-align:right;"><code>ssyevr_</code>, <code>dsyevr_</code>, <code>cheevr_</code>, <code>zheevr_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>cholesky(Hermitian(A))</code></td><td style="text-align:right;"><code>spotrf_</code>, <code>dpotrf_</code>, <code>cpotrf_</code>, <code>zpotrf_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr></tbody></table><h2 id="判定の範囲" tabindex="-1">判定の範囲 <a class="header-anchor" href="#判定の範囲" aria-label="Permalink to &quot;判定の範囲 {#判定の範囲}&quot;">​</a></h2><ul><li><p>「成功」は、このプローブの小さな有限値入力で参照計算または分解の残差を満たしたことを表します。</p></li><li><p>行列積・求解・分解再構成の残差は、BLAS を呼ばないスカラーの積和で確認します。</p></li><li><p>「既存バックエンド」での成功は、Rust colmat の該当分解が接続済みであるという意味ではありません。</p></li><li><p>Rust 側の機能名は固定 revision の <code>faer/src/linalg/solvers.rs</code> で確認した対応候補です。未接続の Rust 関数をこのプローブが直接実行したとは主張しません。</p></li><li><p>この表は全 BLAS / LAPACK の網羅検証ではありません。特異行列、非有限値、一般化固有値、他 OS の結果も含みません。</p></li><li><p>LP64 の直接 ABI テストや負ストライド等の既存回帰テストとは別の、Julia 高水準 API の確認です。</p></li></ul><h2 id="再生成" tabindex="-1">再生成 <a class="header-anchor" href="#再生成" aria-label="Permalink to &quot;再生成 {#再生成}&quot;">​</a></h2><p>リポジトリのルートで、ビルド後の新しい Julia プロセスから実行します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/support_matrix.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output=docs/src/reference/support-matrix.md</span></span></code></pre></div><p>検証が失敗したときは表を上書きしません。呼び出しケースと検証方法は <code>test/support_matrix.jl</code> にあります。</p><h2 id="Householder-ABI-接続（#264）" tabindex="-1">Householder ABI 接続（#264） <a class="header-anchor" href="#Householder-ABI-接続（#264）" aria-label="Permalink to &quot;Householder ABI 接続（#264） {#Householder-ABI-接続（#264）}&quot;">​</a></h2><p>この追記は既存の Linux 実測表とは別の検証です。Julia 1.13.3 / <code>x86_64-apple-darwin</code>、colmat-rs <code>e1c83482f5a61449d30e989808c3ba5f751ec391</code> を使用しました。 <code>test/householder.jl</code> は <code>larf/larfx/larfy/larft/larfb/larfg/larfgp</code> の 4型・LP64/ILP64 の共有ライブラリ入口を具体的な C 署名で実行し、 28 canonical シンボルの LBT 登録先が Colmat であることを確認します。</p><p>生成は LAPACK の <code>I - tau*v*v&#39;</code>、実数 beta、LARFGP の非負 beta に合わせた Rust adapter です。colmat の実数係数・複素位相を保持する生成 API の単なる 逆数変換ではありません。適用は既存の native GEMV/SYMV/GEMM を使用します。 F/B、C/R の implicit unit diagonal を展開し、LARFT の三角因子を構成します。 LARFB は LAPACK 形式の外部因子も受け入れます。</p><p>検証は反射積・ユニタリ性・極小/極大尺度・複素 head・ゼロ係数・ 長さ1・正負 stride・左右・上下三角・外部 OpenBLAS の LARFT 因子を含みます。 LARFX の小次数では WORK を参照せず、LARFY は選択した三角領域だけを更新します。 これらの補助ルーチンには workspace query や INFO 引数はありません。 不正引数の診断は既存の <code>colmat_blas_last_error</code> 規約を使います。</p><p>LARFB は内部で basis と次数の二乗の明示的な反射行列を確保します。 呼び出し側の最小合法 WORK で動作しますが、作業領域だけを使う実装や LAPACK と同じ計算量・割り当て量を保証するものではありません。 この接続は Fortran ABI に限定し、LAPACKE は別タスクです。</p><h2 id="Compact-QR-接続（#290）" tabindex="-1">Compact QR 接続（#290） <a class="header-anchor" href="#Compact-QR-接続（#290）" aria-label="Permalink to &quot;Compact QR 接続（#290） {#Compact-QR-接続（#290）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と上記固定 colmat-rs revision で、 通常の <code>qr(A)</code>、<code>Matrix(F.Q)</code>、Q/Q&#39; の左右適用を Colmat の GEQRT/GEMQRT 入口に接続しました。既存 Linux snapshot の未接続という 記録は、その時点の結果として保持しています。</p><p><code>test/qr_compact.jl</code> は4型、LP64/ILP64 の具体的な C 署名、NB=1/2/4、 GEQRT2/GEQRT3、外部 OpenBLAS の因子との双方向相互運用、leading dimension、 空行列、ゼロ列・従属列、極小尺度、不正引数を検証します。 これらの入口には LWORK query はありません。WORK は標準の最小長で実行します。</p><p>native QR は各 active column に適用し、実数の native 係数の逆数から LAPACK の T を構成します。これにより、native の rank 処理がゼロ列を 詰める場合も LAPACK の対角位置を保ちます。複素 R の対角位相を保持し、 Q と R の積・外部 LAPACK による反射適用を検証します。 GEQRT3 も共通の数値経路を使い、Netlib の再帰算法とは異なります。 内部配列を確保し、GEMQRT は各ブロックを明示的に展開します。</p><h2 id="通常-QR-接続（#289）" tabindex="-1">通常 QR 接続（#289） <a class="header-anchor" href="#通常-QR-接続（#289）" aria-label="Permalink to &quot;通常 QR 接続（#289） {#通常-QR-接続（#289）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 GEQRF/GEQR2、非負対角版、ORGQR/UNGQR/ORG2R/UNG2R、 ORMQR/UNMQR/ORM2R/UNM2R、GEQRS の36シンボルを両整数 ABI に接続しました。 <code>test/qr_standard.jl</code> は Julia ラッパー経由の再構成・Q の左右適用に加え、 両 ABI の直接実行、外部 OpenBLAS 因子の受け入れと native 因子の外部適用、 非負対角、workspace query と最小合法作業領域、padded leading dimension、 空・矩形・ゼロ列、GEQRS の最小二乗残差を検証します。</p><p>実数通常版は native QR の block-size-one 係数から A/TAU を作ります。 複素通常版と非負対角版は LAPACK gauge reflector 生成を使い、 実数 beta と複素 TAU を Julia の標準規約に合わせます。 Q の適用は native GEMV、GEQRS の三角 solve は native 三角 kernel に接続します。 内部配列を確保するため、呼び出し側の WORK 以外にもメモリを使用します。 GEQRS は deprecated LAPACK 契約に従い、workspace query を提供しません。</p><h2 id="列ピボット-QR-接続（#299）" tabindex="-1">列ピボット QR 接続（#299） <a class="header-anchor" href="#列ピボット-QR-接続（#299）" aria-label="Permalink to &quot;列ピボット QR 接続（#299） {#列ピボット-QR-接続（#299）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 GEQP3/GEQPF/GEQP3RK の12シンボルを4型・両整数 ABI に接続しました。 <code>qr(A, ColumnNorm())</code> は GEQP3 から native QR/reflector 適用へ到達します。 固定 JPVT 列は入力順を保って先頭へ移し、出力は元の列番号を1始まりで返します。</p><p>GEQP3RK は KMAX と、残差部分の最大列2ノルムに対する ABSTOL/RELTOL で停止します。 各段階で列ノルムを再計算するため、native ColPivQr の対角値による rank 判定や Netlib の部分ノルム更新とは異なる計算量・丸め経路です。付随 NRHS 列は ピボット選択から除外し、Q&#39; を適用します。NaN/Inf の INFO、ゼロ・極小 tolerance、 rank と残差ノルムの返却を別々に扱います。内部配列を確保します。</p><p><code>test/qr_pivoted.jl</code> で両 ABI の具体的な C 署名、固定列、外部 OpenBLAS 因子、 途中停止した分解の再構成、独立計算した残差ノルム、付随右辺、 query と最小合法 workspace、leading dimension、空行列・1×1・ゼロ行列、 NaN/Inf 診断、LBT 登録を検証します。空行列の Julia GEQP3 ラッパーは native 入口を呼ばないため、直接 ABI の空行列ケースと区別します。</p><h2 id="LQ-接続（#291）" tabindex="-1">LQ 接続（#291） <a class="header-anchor" href="#LQ-接続（#291）" aria-label="Permalink to &quot;LQ 接続（#291） {#LQ-接続（#291）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 通常・ブロック・short-wide・ヘッダー形式の LQ、Q の生成・左右適用、 GELQS の56シンボルを4型・両整数 ABI に接続しました。 通常 LQ は随伴 QR の恒等式を使い、A/TAU と行保存のブロック T を構成します。 short-wide 形式は最初の NB 列の因子と、後続の [L B] パネルの因子を LAPACK と同じ順序で格納します。外部の T とヘッダーを受け入れます。</p><p>GELQ は合法な MB=1・NB=N の形式を選ぶため、最適・最小 query の推奨値が 一致します。GELQT3 は共通の分解経路であり Netlib の再帰算法ではありません。 内部で随伴行列・反射・選択パネルなどを確保します。GELQS は deprecated LAPACK 契約に従い workspace query を提供しません。</p><p><code>test/lq.jl</code> は4型・両 ABI、通常 Julia ラッパー、最小合法 workspace、 最小ヘッダー query、ブロック端、外部 OpenBLAS 因子との双方向相互運用、 左右・転置・共役、leading dimension の padding、空・矩形・階数落ち、 GELQS の残差と最小ノルム性、56シンボルの LBT 登録を検証します。</p><h2 id="RZ-接続（#304）" tabindex="-1">RZ 接続（#304） <a class="header-anchor" href="#RZ-接続（#304）" aria-label="Permalink to &quot;RZ 接続（#304） {#RZ-接続（#304）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 TZRZF/TZRQF/LATRZ、ORMRZ/UNMRZ、LARZ/LATZM、LARZT/LARZB の 32シンボルを4型・両整数 ABI に接続しました。upper trapezoid の <code>A = [R 0] Z</code> を後ろの行から構成し、疎な反射を native GEMV/GEMM で適用します。 LARZT/LARZB は LAPACK の backward・行保存を扱い、複素 T の共役も変換します。 単反射・ブロック反射とも作用しない中央領域を保持し、内部配列を確保します。</p><p><code>test/rz.jl</code> は両 ABI の直接呼び出し、Julia ラッパー、外部 OpenBLAS の 因子・適用との相互運用、query と最小合法 workspace、padding、正負 stride、 分離された C1/C2、L=0 と暗黙成分に重なる尾部、中央領域を NaN にした入力、 直交性・再構成・共役適用と LBT 登録を検証します。</p><h2 id="最小二乗-driver-接続（#310）" tabindex="-1">最小二乗 driver 接続（#310） <a class="header-anchor" href="#最小二乗-driver-接続（#310）" aria-label="Permalink to &quot;最小二乗 driver 接続（#310） {#最小二乗-driver-接続（#310）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 GELS/GELST/GETSLS、GELSS/GELSD、GELSY/GELSX の28シンボルを4型・両整数 ABI に接続しました。 full-rank 系は QR/LQ と三角 solve で tall/wide と転置・共役を処理し、 A/B を尺度調整して解・残差・因子の尺度を戻します。 GELSS/GELSD は共通 native SVD で RCOND と rank を判定します。 GELSS の A には行方向の右特異ベクトルを返します。GELSD の query は WORK に加え IWORK/RWORK の必要長を返します。</p><p>GELSY/GELSX は固定 JPVT の列ピボット QR、leading R の条件判定、RZ、 Q/Z 適用、逆置換による完全直交分解です。条件判定には leading R の 特異値を使うため、Netlib の増分条件推定とは境界付近の rank が異なる可能性があります。 GELST/GETSLS は共通 full-rank 経路で、Netlib の compact-WY/TS 算法と同一ではありません。 GETSLS は最適・最小 query の値が一致する構成です。SVD の full U や中間行列などを 内部で確保し、GELSD という名称でも native divide-and-conquer の実行を保証しません。</p><p><code>test/least_squares.jl</code> は両 ABI の具体的な C 署名、外部 OpenBLAS との比較、 固定列、rank-deficient と過少決定の最小ノルム解、特異値・右特異ベクトル、 TRANS/共役、残差配置、極小/極大尺度、padding、最小 workspace と query、 空・ゼロ入力、28シンボルの LBT 登録を検証します。</p><h2 id="Hessenberg-接続（#293）" tabindex="-1">Hessenberg 接続（#293） <a class="header-anchor" href="#Hessenberg-接続（#293）" aria-label="Permalink to &quot;Hessenberg 接続（#293） {#Hessenberg-接続（#293）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 GEHRD/GEHD2、ORGHR/UNGHR、ORMHR/UNMHR の16シンボルを4型・両整数 ABI に接続しました。 LAPACK gauge の reflector 生成と native GEMV による左右適用で A/TAU を構成し、 複素 subdiagonal を実数にします。GEHRD/GEHD2 は共通経路で、ブロック化の差はありません。 ILO/IHI の部分範囲に対応し、Q はその範囲外で恒等変換です。 内部で反射・Q 生成用の配列を確保します。</p><p><code>test/hessenberg.jl</code> は Julia ラッパー、両 ABI の具体的な C 署名、 外部 OpenBLAS の因子と Q との相互運用、A=Q_H_Q&#39;、直交性、active range 外の 保存、空・1×1、左右・転置・共役、padding、最小 workspace と query、 不正範囲と LBT 登録を検証します。</p><h2 id="Schur-driver-接続（#300）" tabindex="-1">Schur driver 接続（#300） <a class="header-anchor" href="#Schur-driver-接続（#300）" aria-label="Permalink to &quot;Schur driver 接続（#300） {#Schur-driver-接続（#300）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 HSEQR/LAHQR/LAQR0/LAQR4/GEES の20シンボルを4型・両整数 ABI に接続しました。 Hessenberg の active block を公開 native Schur API へ渡し、範囲外との結合と 既存 Z を native GEMM で更新します。COMPZ=N/I/V、JOB=E/S、 補助入口の WANTT/WANTZ と ILOZ/IHIZ を扱います。JOB=E/WANTT=false でも Schur 形式まで計算します。各入口は同じ native QR 経路を使い、Netlib の LAHQR/LAQR0/LAQR4 の算法の切り替えを再現するものではありません。</p><p>GEES は Hessenberg 還元、native Schur、native block reorder を合成します。 尺度を正規化してから還元・反復・並べ替えを行い、SELECT には元の単位の 固有値を渡します。SELECT の Fortran LOGICAL は整数 ABI と同じ幅で扱い、 実数共役対は片方が選択されれば両方を選択します。SDIM と選択された スペクトルの前方配置を返し、並べ替え拒否と再選択の不整合はそれぞれ INFO=N+1/N+2 です。SORT=N と workspace query では callback を呼びません。 GEESX/TRSEN の条件推定はこの接続に含みません。</p><p>公開 native Schur API は非収束の部分 index を返しません。その場合は active range 全体を未収束として INFO=IHI を返し、部分収束を偽って報告しません。 内部で行列・反射係数・native scratch を確保し、呼び出し元の最小合法 WORK で 実行できます。query はその必要長を返します。</p><p><code>test/schur.jl</code> は4型・両 ABI の具体的な C 署名、Julia の通常ラッパー、 A=Z_T_Z&#39;、直交性、active range、既存 Z の更新と行範囲、実 Schur 共役対、 SELECT/SDIM、極小・極大尺度、padding、未参照領域の NaN、空・1×1、 query、不正引数、非収束 INFO と20シンボルの LBT 登録を検証します。</p><h2 id="一般化-Hessenberg-接続（#269）" tabindex="-1">一般化 Hessenberg 接続（#269） <a class="header-anchor" href="#一般化-Hessenberg-接続（#269）" aria-label="Permalink to &quot;一般化 Hessenberg 接続（#269） {#一般化-Hessenberg-接続（#269）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 GGHRD/GGHD3 の8シンボルを4型・両整数 ABI に接続しました。 公開 <code>generalized_hessenberg</code> が返す active block の左右基底を全体へ埋め込み、 範囲外との結合と既存 Q/Z を native GEMM で更新します。 COMPQ/COMPZ=N/I/V と ILO/IHI を扱い、B の厳密下三角は入力で読みません。 GGHRD/GGHD3 は同じ native 経路で、内部の行列・scratch を確保します。 GGHD3 は呼び出し元の WORK を1要素だけ必要とし、query でも1を返します。 Netlib GGHRD/GGHD3 の別々の算法や外部 WORK の利用方法を再現しません。</p><p><code>test/generalized_hessenberg.jl</code> は両 ABI の具体的な C 署名、4型、 Q&#39;_A_Z=H と Q&#39;_B_Z=T、Hessenberg/三角構造、ユニタリ性、 空・1×1・2×2、部分範囲、Q/Z の初期化・既存値への更新・未使用、 40×40 のブロック経路、padding、未参照 B/Q/Z の NaN、query、 不正引数と8シンボルの LBT 登録を検証します。</p><h2 id="QZ-driver-接続（#294）" tabindex="-1">QZ driver 接続（#294） <a class="header-anchor" href="#QZ-driver-接続（#294）" aria-label="Permalink to &quot;QZ driver 接続（#294） {#QZ-driver-接続（#294）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 HGEQZ/GGES/GGES3/GEGS の16シンボルを4型・両整数 ABI に接続しました。 HGEQZ は active block の native QZ と基底変換を合成し、 COMPQ/COMPZ=N/I/V と ILO/IHI を扱います。 JOB=E でも内部では Schur 形式まで計算します。 β の対角を非負の実数に揃え、Q/Z と pencil の変換を維持します。 α/β は homogeneous な組で返し、β=0 を有限の固有値へ置き換えません。</p><p>GGES/GGES3/GEGS は QR による B の三角化、一般化 Hessenberg 還元、native QZ を 合成します。A/B は独立に尺度を正規化し、α/β と S/T の単位を戻します。 GGES/GGES3 の SELECT は LP64/ILP64 の LOGICAL 幅で呼び、実数共役対の 片方が選択されれば両方を選択します。選択された block を native reorder で 前方へ移し、並べ替えた pencil の QZ を再評価して α/β を更新します。 query と SORT=N では callback を呼びません。並べ替え拒否は INFO=N+3、 再選択の不整合は INFO=N+2 です。GGESX/TGSEN の条件推定は対象外です。</p><p>公開 native QZ API は非収束状態・部分 index を返しません。 返却された Schur 構造と homogeneous な α/β の各成分の有限性を確認し、不完全な結果は active range 全体を未収束として INFO=IHI とします。 内部行列と scratch を確保し、入口ごとに LAPACK の最小合法 WORK と query を 提供します。GGES/GGES3/GEGS は共通経路で、Netlib の各 driver の ブロック化や permutation balancing の実装を再現するものではありません。</p><p><code>test/qz.jl</code> は両 ABI の具体的な C 署名、4型、pencil の再構成、 Schur 構造、ユニタリ性、active range、Q/Z の初期化・更新・未使用、 40×40 の入力、homogeneous 値の独立 OpenBLAS 比較、β=0、実数共役対、 SELECT/SDIM、独立した極小・極大尺度、padding、未参照領域の NaN、 空・1×1・2×2、query と最小 WORK、不正引数、非収束 INFO、 Julia GGES ラッパーと16シンボルの LBT 登録を検証します。</p><h2 id="一般化-EVD-driver-接続（#301）" tabindex="-1">一般化 EVD driver 接続（#301） <a class="header-anchor" href="#一般化-EVD-driver-接続（#301）" aria-label="Permalink to &quot;一般化 EVD driver 接続（#301） {#一般化-EVD-driver-接続（#301）}&quot;">​</a></h2><p>Julia 1.13.3 / x86_64-apple-darwin と同じ固定 colmat-rs revision で、 GGEV/GGEV3/GEGV/GGEVX の16シンボルを4型・両整数 ABI に接続しました。 通常 driver は公開 <code>gevd_real/cplx</code> の homogeneous α/β と左右固有ベクトルを 変換します。β=0 と 0/0 の特異 pencil を保持し、実数共役対を隣接する実部・虚部列で 返します。native の実数 transpose-left 規約は虚部列を反転して LAPACK の adjoint-left 規約へ変換し、各ベクトルの最大の |Re|+|Im| を1に正規化します。 各入口は同じ native 経路と内部 scratch を使い、入口ごとの最小 WORK/query を返します。 native GEVD が非収束を返す場合は、部分 index がないため INFO=N とします。</p><p>GGEVX の <code>BALANC=N/SENSE=N</code> は native です。ILO/IHI=1/N、LSCALE/RSCALE=1 と 元の行列の ABNRM/BBNRM を返します。A/B の Schur 出力は、固定 revision の native 実装の2冪 prescale を追跡して元の単位へ戻します。依存更新時にはこの変換を 再検証する必要があります。</p><p>その他の BALANC/SENSE は既存 ILP64 expert backend へ委譲します。 LP64 の呼び出しでは整数スカラーを64 bitへ変換し、IWORK/BWORK は呼び出し内で 確保するため、32 bit の出力領域へ64 bitで書き込みません。ILO/IHI/INFO を元の幅へ戻し、 query 時には ILO/IHI を変更しません。balance と条件推定を native 対応済みとは扱いません。 Colmat のロード前に4型の ILP64 GGEVX が必要です。通常の Julia は OpenBLAS を提供します。 不足時は LBT 登録の変更前に明示的な設定エラーを返し、合法なモードを不正引数として 報告したり、未計算の条件推定を成功扱いにしたりしません。 再登録では Colmat 自身を expert backend として保存しません。</p><p><code>test/generalized_eigen.jl</code> は4型・両 ABI・全4入口、左右・片側・values-only、 homogeneous な左右残差、β=0、0/0、実数共役対と正規化、独立 OpenBLAS 比較、 GGEVX の全 BALANC/SENSE 組合せ、metadata、query、整数幅の guard、padding、 元の尺度の Schur 出力、空・1×1、不十分な workspace と LBT 登録を検証します。 別プロセスで expert backend 欠落時の登録前診断と再登録も確認します。</p>',63)])])}const p=e(i,[["render",r]]);export{x as __pageData,p as default};
